 CREATE OR REPLACE FUNCTION public.listpersonabusesubstance(personid uuid, pagenumber bigint, pagesize bigint)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
  RETURNS TABLE(personabusesubstanceid uuid, isusetobacco boolean, tobaccoageatfirstuse character varying, tobaccofrequencytypekey character varying, tobaccofrequencytypedescription character varying, tobaccotimes integer, isusedrug boolean, drugageatfirstuse character varying, drugfrequencytypekey character varying, drugfrequencytypedescription character varying, drugtimes integer, isusealcohol boolean, alcoholageatfirstuse character varying, alcoholfrequencytypekey character varying, alcoholfrequencytypedescription character varying, alcoholtimes integer, drugoralcoholproblems character varying, isusedrugoralcohol boolean, createddate timestamp without time zone)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         v_pageoffset int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         v_pagenumber int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         v_personid uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         v_pagenumber := pagenumber-1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         v_pageoffset = v_pagenumber * pagesize;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         v_personid := personid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             -- count(1) over(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
             select PAS.personabusesubstanceid ,PAS.isusetobacco, PAS.tobaccoageatfirstuse, PAS.tobaccofrequencytypekey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
             PASFT.description, PAS.tobaccotimes, PAS.isusedrug, PAS.drugageatfirstuse,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             PAS.drugfrequencytypekey,PASFT1.description,PAS.drugtimes,PAS.isusealcohol, PAS.alcoholageatfirstuse,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             PAS.alcoholfrequencytypekey,PASFT2.description,PAS.alcoholtimes,PAS.drugoralcoholproblems,PAS.isusedrugoralcohol, PAS.insertedon                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             from personabusesubstance as PAS                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             LEFT JOIN personabusesubstancefrequencytype as PASFT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                       ON PASFT.personabusesubstancefrequencytypekey = PAS.tobaccofrequencytypekey and PASFT.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             LEFT JOIN personabusesubstancefrequencytype as PASFT1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                       ON PASFT1.personabusesubstancefrequencytypekey = PAS.drugfrequencytypekey and PASFT1.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
             LEFT JOIN personabusesubstancefrequencytype as PASFT2                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                       ON PASFT2.personabusesubstancefrequencytypekey = PAS.alcoholfrequencytypekey and PASFT2.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
             where PAS.personid = v_personid and PAS.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 ORDER BY PAS.updatedon desc  limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 --LIMIT pagesize OFFSET v_pageoffset;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      

